insert into items (key, name, description, sprite_url, price, effect, in_shop, shop_badges, shop_area, region, once_only) values
  ('antidote', 'Antidote', 'Cures a poisoned Pokémon. In battle.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/items/antidote.png', 10, '{"kind":"cure","statuses":["poison"]}'::jsonb, true, 0, null, null, false),
  ('paralyze-heal', 'Paralyze Heal', 'Cures paralysis — the Pokémon can act this very turn. In battle.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/items/paralyze-heal.png', 12, '{"kind":"cure","statuses":["paralyze"]}'::jsonb, true, 0, null, null, false),
  ('burn-heal', 'Burn Heal', 'Cures a burn. In battle.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/items/burn-heal.png', 12, '{"kind":"cure","statuses":["burn"]}'::jsonb, true, 1, null, null, false),
  ('ice-heal', 'Ice Heal', 'Thaws a frozen Pokémon — it can act this very turn. In battle.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/items/ice-heal.png', 12, '{"kind":"cure","statuses":["frozen"]}'::jsonb, true, 2, null, null, false),
  ('ether', 'Ether', 'Gives the Pokémon in battle one reroll back (up to its maximum).', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/items/ether.png', 40, '{"kind":"rerolls","amount":1}'::jsonb, true, 3, null, null, false),
  ('max-ether', 'Max Ether', 'Gives the Pokémon in battle three rerolls back (up to its maximum).', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/items/max-ether.png', 100, '{"kind":"rerolls","amount":3}'::jsonb, true, 6, null, null, false),
  ('rare-candy', 'Rare Candy', 'Raises a Pokémon by one level. Use it from the Team screen.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/items/rare-candy.png', 300, '{"kind":"level","amount":1}'::jsonb, false, 0, null, null, false),
  ('poke-ball', 'Poké Ball', 'Adds 1 to the catch die.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/items/poke-ball.png', 20, '{"kind":"ball","bonus":1}'::jsonb, true, 0, null, null, false),
  ('great-ball', 'Great Ball', 'A good ball: adds 2 to the catch die.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/items/great-ball.png', 50, '{"kind":"ball","bonus":2}'::jsonb, true, 2, null, null, false),
  ('ultra-ball', 'Ultra Ball', 'A high-performance ball: adds 3 to the catch die.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/items/ultra-ball.png', 100, '{"kind":"ball","bonus":3}'::jsonb, true, 4, null, null, false),
  ('friend-ball', 'Friend Ball', 'More chances to discover hidden talents on catch depending on your best streak, current: ×{x}.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/items/friend-ball.png', 100, '{"kind":"ball","bonus":3,"talentBoost":true}'::jsonb, false, 0, null, null, false),
  ('master-ball', 'Master Ball', 'The best ball there is. It never misses.', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/items/master-ball.png', 1000, '{"kind":"ball","bonus":10}'::jsonb, false, 0, null, null, false),
  ('raid-ball', 'Raid Ball', 'A ball made for raids: adds 5 to the catch die. It can only be thrown in a raid.', '/items/raid-ball.png', 500, '{"kind":"ball","bonus":5,"raidOnly":true}'::jsonb, false, 0, null, null, false),
